#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node *reverse_list(Node *head)
{
    Node *prev = NULL;      /* line 1 */
    Node *curr = head;      /* line 2 */
    Node *next = NULL;      /* line 3 */

    while (curr != NULL) {  /* line 4 */
        next = curr->next;  /* line 5 */
        curr->next = prev;  /* line 6 */
        prev = curr;        /* line 7 */
        curr = next;        /* line 8 */
    }

    return prev;            /* line 9 */
}
